//! CLDR 48 unit formatting.
//!
//! Unit patterns live in units_data.bin, generated by
//! tools/unicode/format/generate_misc.py from the CLDR unit blocks.

const std = @import("std");
const data = @import("units_data.zig");
const blob = @embedFile("units_data.bin");
const misc = @import("misc.zig");
const number = @import("number.zig");
const plural = @import("plurals.zig");

pub const Unit = data.Unit;

const header_len = 24;
const locale_count = readU16(8);
const unit_count = readU16(10);
const entry_count = readU32(12);
const string_length = readU32(16);

const locale_offset = header_len;
const entry_offset = locale_offset + @as(usize, locale_count) * 16;
const strings_offset = entry_offset + @as(usize, entry_count) * 8;

comptime {
    if (blob.len < header_len or !std.mem.eql(u8, blob[0..4], "CJUN") or
        blob[4] != 1)
    {
        @compileError("invalid unit data");
    }
    if (strings_offset + @as(usize, string_length) != blob.len) {
        @compileError("invalid unit data lengths");
    }
    if (unit_count != data.unit_ids.len) {
        @compileError("unit data does not match the unit enum");
    }
}

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, blob[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, blob[offset..][0..4], .little);
}

fn strAt(offset: u32) []const u8 {
    if (offset == 0) return "";
    return std.mem.sliceTo(blob[strings_offset + @as(usize, offset) ..], 0);
}

fn localeId(index: usize) []const u8 {
    const base = locale_offset + index * 16;
    const id_offset = readU32(base);
    const id_length = blob[base + 4];
    return blob[strings_offset + @as(usize, id_offset) ..][0..id_length];
}

fn findLocaleRecord(locale_name: []const u8) ?usize {
    var low: usize = 0;
    var high: usize = locale_count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (std.mem.order(u8, localeId(middle), locale_name)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return middle,
        }
    }
    return null;
}

fn localeRecord(locale_name: []const u8) ?usize {
    if (findLocaleRecord(locale_name)) |index| return index;
    if (std.mem.indexOfAny(u8, locale_name, "-_")) |position| {
        if (findLocaleRecord(locale_name[0..position])) |index| return index;
    }
    return findLocaleRecord("en");
}

pub const Style = enum { long, short };

pub const Options = struct {
    style: Style = .long,
};

pub const Error = error{
    OutOfMemory,
    InvalidPattern,
    MissingCurrency,
    InvalidUnit,
};

/// CLDR identifier for a unit, such as "length-meter".
pub fn unitId(unit: Unit) []const u8 {
    return data.unit_ids[@intFromEnum(unit)];
}

/// Resolve a CLDR unit identifier such as "speed-kilometer-per-hour".
pub fn unitFromId(id: []const u8) ?Unit {
    var low: usize = 0;
    var high = data.unit_ids.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        switch (std.mem.order(u8, data.unit_ids[middle], id)) {
            .lt => low = middle + 1,
            .gt => high = middle,
            .eq => return @enumFromInt(middle),
        }
    }
    return null;
}

fn patternAt(
    record_index: usize,
    unit: Unit,
    style: Style,
    category: plural.Category,
) []const u8 {
    const base = locale_offset + record_index * 16;
    const start = readU32(base + 8);
    const count = readU16(base + 12);
    const key: u16 = @as(u16, @intFromEnum(unit)) * 12 +
        @as(u16, @intFromEnum(style)) * 6 +
        @as(u16, @intFromEnum(category));
    var low: usize = start;
    var high: usize = @as(usize, start) + count;
    while (low < high) {
        const middle = low + (high - low) / 2;
        const entry_base = entry_offset + middle * 8;
        const candidate = readU16(entry_base);
        if (candidate < key) {
            low = middle + 1;
        } else if (candidate > key) {
            high = middle;
        } else {
            return strAt(readU32(entry_base + 2));
        }
    }
    return "";
}

pub fn formatAlloc(
    allocator: std.mem.Allocator,
    value: f64,
    unit: Unit,
    locale: []const u8,
    options: Options,
) Error![]u8 {
    // ICU's short measure format uses the dedicated percent pattern for
    // percent and permille, which formats the number without a unit suffix.
    const bare = options.style == .short and
        (unit == .percent or unit == .permille);

    const category = misc.pluralCategory(locale, value);
    var pattern: []const u8 = "";
    if (localeRecord(locale)) |index| {
        pattern = patternAt(index, unit, options.style, category);
        if (pattern.len == 0) {
            pattern = patternAt(index, unit, options.style, .other);
        }
    }
    if (pattern.len == 0 and !bare) {
        if (findLocaleRecord("en")) |index| {
            pattern = patternAt(index, unit, options.style, category);
            if (pattern.len == 0) {
                pattern = patternAt(index, unit, options.style, .other);
            }
        }
    }
    if (pattern.len == 0 and !bare) return error.InvalidPattern;

    const formatted = try number.formatAlloc(allocator, value, locale, .{});
    if (bare) return formatted;
    defer allocator.free(formatted);
    return misc.replacePlaceholderAlloc(allocator, pattern, formatted);
}

/// Apply a unit pattern to an already formatted number.
pub fn applyNumberAlloc(
    allocator: std.mem.Allocator,
    plural_value: f64,
    number_text: []const u8,
    unit: Unit,
    locale: []const u8,
    style: Style,
) error{ InvalidPattern, OutOfMemory }![]u8 {
    return applyNumberCategoryAlloc(
        allocator,
        misc.pluralCategory(locale, plural_value),
        number_text,
        unit,
        locale,
        style,
    );
}

/// Apply a unit pattern selected by an explicit plural category, used for
/// ranges whose category comes from CLDR plural ranges.
pub fn applyNumberCategoryAlloc(
    allocator: std.mem.Allocator,
    category: plural.Category,
    number_text: []const u8,
    unit: Unit,
    locale: []const u8,
    style: Style,
) error{ InvalidPattern, OutOfMemory }![]u8 {
    var pattern: []const u8 = "";
    if (localeRecord(locale)) |index| {
        pattern = patternAt(index, unit, style, category);
        if (pattern.len == 0) pattern = patternAt(index, unit, style, .other);
    }
    if (pattern.len == 0) {
        if (findLocaleRecord("en")) |index| {
            pattern = patternAt(index, unit, style, category);
            if (pattern.len == 0) {
                pattern = patternAt(index, unit, style, .other);
            }
        }
    }
    if (pattern.len == 0) return error.InvalidPattern;
    return misc.replacePlaceholderAlloc(allocator, pattern, number_text);
}

/// Format a value for a CLDR unit identifier.
pub fn formatUnitIdAlloc(
    allocator: std.mem.Allocator,
    value: f64,
    unit_id: []const u8,
    locale: []const u8,
    options: Options,
) Error![]u8 {
    const unit = unitFromId(unit_id) orelse return error.InvalidUnit;
    return formatAlloc(allocator, value, unit, locale, options);
}

test "unit formatting" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;

    const cases = [_]struct {
        value: f64,
        unit: Unit,
        locale: []const u8,
        style: Style,
        expected: []const u8,
    }{
        .{ .value = 1, .unit = .meter, .locale = "en", .style = .long, .expected = "1 meter" },
        .{ .value = 5, .unit = .meter, .locale = "en", .style = .long, .expected = "5 meters" },
        .{ .value = 3.5, .unit = .kilogram, .locale = "en", .style = .long, .expected = "3.5 kilograms" },
        .{ .value = 2, .unit = .hour, .locale = "en", .style = .long, .expected = "2 hours" },
        .{ .value = 0, .unit = .celsius, .locale = "en", .style = .long, .expected = "0 degrees Celsius" },
        .{ .value = 50, .unit = .percent, .locale = "en", .style = .long, .expected = "50 percent" },
        .{ .value = 5, .unit = .meter, .locale = "en", .style = .short, .expected = "5 m" },
        .{ .value = -3, .unit = .celsius, .locale = "en", .style = .short, .expected = "-3°C" },
        .{ .value = 2, .unit = .hour, .locale = "ru", .style = .long, .expected = "2 часа" },
        .{ .value = 5, .unit = .hour, .locale = "ru", .style = .long, .expected = "5 часов" },
        .{ .value = 1, .unit = .hour, .locale = "ru", .style = .long, .expected = "1 час" },
        .{ .value = 2, .unit = .hour, .locale = "fr", .style = .long, .expected = "2\u{00A0}heures" },
        .{ .value = 5, .unit = .meter, .locale = "zh", .style = .long, .expected = "5米" },
        .{ .value = 2, .unit = .hour, .locale = "zh", .style = .long, .expected = "2小时" },
        .{ .value = 5, .unit = .meter, .locale = "en-GB", .style = .long, .expected = "5 meters" },
        .{ .value = 5, .unit = .meter, .locale = "zz", .style = .long, .expected = "5 meters" },
    };

    for (cases) |case| {
        const result = try formatAlloc(
            allocator,
            case.value,
            case.unit,
            case.locale,
            .{ .style = case.style },
        );
        defer allocator.free(result);
        try testing.expectEqualStrings(case.expected, result);
    }
}

test "unit formatting covers additional locales" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;

    const cases = [_]struct {
        value: f64,
        unit: Unit,
        locale: []const u8,
        expected: []const u8,
    }{
        .{ .value = 5, .unit = .meter, .locale = "de", .expected = "5 Meter" },
        .{ .value = 1, .unit = .meter, .locale = "es", .expected = "1 metro" },
        .{ .value = 5, .unit = .meter, .locale = "es", .expected = "5 metros" },
        .{ .value = 5, .unit = .meter, .locale = "it", .expected = "5 metri" },
        .{ .value = 5, .unit = .meter, .locale = "nl", .expected = "5 meter" },
        .{ .value = 2, .unit = .meter, .locale = "pl", .expected = "2 metry" },
        .{ .value = 5, .unit = .meter, .locale = "pl", .expected = "5 metr\u{00F3}w" },
        .{ .value = 5, .unit = .meter, .locale = "tr", .expected = "5 metre" },
        .{ .value = 5, .unit = .meter, .locale = "ko", .expected = "5\u{BBF8}\u{D130}" },
        .{ .value = 5, .unit = .meter, .locale = "fi", .expected = "5 metri\u{00E4}" },
        .{ .value = 5, .unit = .meter, .locale = "cs", .expected = "5 metr\u{016F}" },
    };
    for (cases) |case| {
        const result = try formatAlloc(
            allocator,
            case.value,
            case.unit,
            case.locale,
            .{ .style = .long },
        );
        defer allocator.free(result);
        try testing.expectEqualStrings(case.expected, result);
    }
}

test "unit identifiers" {
    const testing = @import("std").testing;
    try testing.expectEqualStrings("length-meter", unitId(.meter));
    try testing.expectEqualStrings("speed-kilometer-per-hour", unitId(.kilometer_per_hour));
    try testing.expectEqualStrings("concentr-percent", unitId(.percent));
    try testing.expectEqual(Unit.meter, unitFromId("length-meter").?);
    try testing.expectEqual(Unit.foot, unitFromId("length-foot").?);
    try testing.expect(unitFromId("length-not-a-unit") == null);
}

test "unit formatting by identifier" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;
    const formatted = try formatUnitIdAlloc(
        allocator,
        5,
        "length-meter",
        "en",
        .{},
    );
    defer allocator.free(formatted);
    try testing.expectEqualStrings("5 meters", formatted);
    try testing.expectError(
        error.InvalidUnit,
        formatUnitIdAlloc(allocator, 5, "length-nope", "en", .{}),
    );
}

test "unit conformance" {
    const testing = @import("std").testing;
    const allocator = testing.allocator;
    const fixture = @embedFile("unit_conformance.bin");
    try testing.expect(fixture.len >= 12);
    try testing.expectEqualStrings("CJU1", fixture[0..4]);
    const case_count = std.mem.readInt(u32, fixture[8..12], .little);
    var cursor: usize = 12;
    var failures: usize = 0;
    var total: usize = 0;
    var printed: usize = 0;
    for (0..case_count) |_| {
        const locale_length = fixture[cursor];
        const unit_length = fixture[cursor + 1];
        const style: Style = if (fixture[cursor + 2] == 0) .long else .short;
        const value: f64 = @bitCast(std.mem.readInt(
            u64,
            fixture[cursor + 4 ..][0..8],
            .little,
        ));
        const expected_length = std.mem.readInt(
            u16,
            fixture[cursor + 12 ..][0..2],
            .little,
        );
        cursor += 16;
        const locale_name = fixture[cursor .. cursor + locale_length];
        cursor += locale_length;
        const unit_id = fixture[cursor .. cursor + unit_length];
        cursor += unit_length;
        const expected = fixture[cursor .. cursor + expected_length];
        cursor += expected_length;
        total += 1;
        const actual = formatUnitIdAlloc(
            allocator,
            value,
            unit_id,
            locale_name,
            .{ .style = style },
        ) catch |err| {
            failures += 1;
            if (printed < 30) {
                printed += 1;
                std.debug.print(
                    "unit mismatch {s} {s}: {s}\n",
                    .{ locale_name, unit_id, @errorName(err) },
                );
            }
            continue;
        };
        defer allocator.free(actual);
        if (!std.mem.eql(u8, actual, expected)) {
            failures += 1;
            if (printed < 30) {
                printed += 1;
                std.debug.print(
                    "unit mismatch {s} {s} {d}: got '{s}' expected '{s}'\n",
                    .{ locale_name, unit_id, value, actual, expected },
                );
            }
        }
    }
    std.debug.print("unit conformance: {d}/{d} passed\n", .{ total - failures, total });
    try testing.expect(failures == 0);
}
